#include "c_quadgrad_d.h"

/*
  Differentiation of c_quadgrad_runtimestep in forward (tangent) mode:
   variations   of useful results: *flux *state
   with respect to varying inputs: gamma *flux qstar1 x0 *state
   Plus diff mem management of: flux:in state:in
*/
int c_quadgrad_runtimestep_d(double qstar1, double qstar1d, double timestep, 
        double gamma, double gammad, double x0, double x0d, double *state, 
        double *stated, double *flux, double *fluxd) {
    double delta;
    double deltad;
    double arg1;
    double arg1d;
    double temp;
    double temp0;
    arg1d = timestep*(qstar1d-qstar1*gammad/gamma)/gamma;
    arg1 = qstar1*timestep/gamma;
    temp = sqrt(arg1);
    deltad = (arg1 == 0.0 ? 0.0 : arg1d/(2.0*temp));
    delta = temp;
    double tau;
    double taud;
    taud = (1.0-tanh(delta)*tanh(delta))*deltad;
    tau = tanh(delta);
    temp = x0*tau/delta;
    temp0 = (x0+delta*tau)/(temp+1.);
    double x1 = temp0;
    double x1d = (x0d+tau*deltad+delta*taud-temp0*(tau*x0d+x0*taud-temp*deltad
    )/delta)/(temp+1.);
    *stated = x1d;
    *state = x1;
    *fluxd = qstar1d - gamma*(x1d-x0d)/timestep - (x1-x0)*gammad/timestep;
    *flux = qstar1 - gamma/timestep*(x1-x0);
    return 0;
}

/*
  Differentiation of c_quadgrad_run in forward (tangent) mode:
   variations   of useful results: *states *qout
   with respect to varying inputs: *gammas
   RW status of diff variables: states:(loc) *states:out gammas:(loc)
                *gammas:in qout:(loc) *qout:out
   Plus diff mem management of: states:in gammas:in qout:in
*/
int c_quadgrad_run_d(int nval, int nreaches, double timestep, double x0, 
        double *gammas, double *gammasd, double *qin, double *states, double *
        statesd, double *qout, double *qoutd) {
    int i, j, k;
    double qi;
    double qid;
    double xini;
    double xinid;
    double gam;
    double gamd;
    *statesd = 0.0;
    *qoutd = 0.0;
    /* Loop through reaches */
    for (i = 0; i < nreaches; ++i) {
        /* initialise reach model */
        xini = x0;
        gamd = gammasd[i];
        gam = gammas[i];
        xinid = 0.0;
        /* Time series loop */
        for (j = 0; j < nval; ++j) {
            /* Get inflow */
            k = j*nreaches + i - 1;
            qid = (i == 0 ? 0.0 : qoutd[k]);
            qi = (i == 0 ? qin[j] : qout[k]);
            /* Run model */
            k = j*nreaches + i;
            c_quadgrad_runtimestep_d(qi, qid, timestep, gam, gamd, xini, xinid
                                     , &(states[k]), &(statesd[k]), &(qout[k])
                                     , &(qoutd[k]));
            /* Set timestep for next iteration */
            xinid = statesd[k];
            xini = states[k];
        }
    }
    return 0;
}
